import json
from pathlib import Path

datasource = {"type": "prometheus", "uid": "prometheus"}
job = 'job="frame-inventory-backend"'
http = job + ',uri!~"/actuator(/.*)?"'
grpc = job + ',rpc_service="frameinventory.v1.FrameManagement"'

def request_rate(metric, labels):
    return f"sum(rate({metric}_seconds_count{{{labels}}}[$__rate_interval]))"

def errors(metric, labels, status):
    total = request_rate(metric, labels)
    failed = request_rate(metric, labels + "," + status)
    return f"100 * ({failed} or 0 * {total}) / ({total} > 0)"

def latency(metric, labels, quantile):
    return (
        f"histogram_quantile({quantile}, "
        f"sum by (le) (rate({metric}_seconds_bucket{{{labels}}}[$__rate_interval])))"
    )

def row(id, title, y):
    return {
        "id": id, "type": "row", "title": title,
        "gridPos": {"h": 1, "w": 24, "x": 0, "y": y},
        "collapsed": False, "panels": [],
    }

def panel(id, title, description, unit, x, y, series, percent=False):
    defaults = {"unit": unit, "min": 0, "color": {"mode": "palette-classic"}}
    if percent:
        defaults["max"] = 100
    return {
        "id": id, "type": "timeseries", "title": title, "description": description,
        "gridPos": {"h": 8, "w": 8, "x": x, "y": y},
        "datasource": datasource,
        "fieldConfig": {"defaults": defaults, "overrides": []},
        "options": {
            "legend": {"displayMode": "list", "placement": "bottom", "showLegend": True},
            "tooltip": {"mode": "multi", "sort": "desc"},
        },
        "targets": [
            {"refId": chr(65 + i), "expr": expr, "legendFormat": label}
            for i, (label, expr) in enumerate(series)
        ],
    }

dashboard = {
    "uid": "frame-inventory-backend",
    "title": "Frame Inventory Backend",
    "description": "Rate, errors, duration, and saturation for the Spring Boot backend.",
    "tags": ["frame-inventory", "backend"],
    "schemaVersion": 39,
    "time": {"from": "now-30m", "to": "now"},
    "refresh": "30s",
    "panels": [
        row(1, "Requests", 0),
        panel(2, "Request rate", "Completed HTTP requests and Frame Management gRPC calls per second. HTTP excludes Actuator endpoints.", "reqps", 0, 1, [
            ("HTTP", request_rate("http_server_requests", http)),
            ("gRPC", request_rate("grpc_server", grpc)),
        ]),
        panel(3, "Error rate", "Percentage of requests returning HTTP 5xx or gRPC non-OK. Series are blank when there is no traffic.", "percent", 8, 1, [
            ("HTTP 5xx", errors("http_server_requests", http, 'status=~"5.."')),
            ("gRPC non-OK", errors("grpc_server", grpc, 'grpc_status_code!="OK"')),
        ], percent=True),
        panel(4, "Request duration", "p50 and p95 of completed requests, calculated from Micrometer histograms.", "s", 16, 1, [
            ("HTTP p50", latency("http_server_requests", http, 0.5)),
            ("HTTP p95", latency("http_server_requests", http, 0.95)),
            ("gRPC p50", latency("grpc_server", grpc, 0.5)),
            ("gRPC p95", latency("grpc_server", grpc, 0.95)),
        ]),
        row(5, "Saturation", 9),
        panel(6, "CPU utilization", "CPU utilization reported by the JVM for the process and the system it runs on.", "percent", 0, 10, [
            ("Process", f"100 * process_cpu_usage{{{job}}}"),
            ("System", f"100 * system_cpu_usage{{{job}}}"),
        ], percent=True),
        panel(7, "JVM heap utilization", "Heap used as a percentage of the reported heap maximum. Undefined pool maxima are excluded.", "percent", 8, 10, [
            ("Heap used", f'100 * sum by (instance) (jvm_memory_used_bytes{{{job},area="heap"}}) / sum by (instance) (jvm_memory_max_bytes{{{job},area="heap"}} > 0)'),
        ]),
        panel(8, "Database connection pool", "Active HikariCP connections, configured capacity, and threads waiting for a connection.", "short", 16, 10, [
            ("Active · {{pool}}", f"hikaricp_connections_active{{{job}}}"),
            ("Capacity · {{pool}}", f"hikaricp_connections_max{{{job}}}"),
            ("Waiting · {{pool}}", f"hikaricp_connections_pending{{{job}}}"),
        ]),
    ],
}
# Grafana substitutes double braces in metric legends.
for target in dashboard["panels"][-1]["targets"]:
    target["legendFormat"] = target["legendFormat"].replace("{pool}", "{{pool}}") if "{{pool}}" not in target["legendFormat"] else target["legendFormat"]

Path("monitoring/dashboards/frame-inventory-backend.json").write_text(json.dumps(dashboard, ensure_ascii=False, indent=2) + "\n")
